export PATH="$HOME/.bun/bin:$PATH"; cd /harness-state/tmp; bun -e '
const d=JSON.parse(await Bun.file("/harness-state/tmp/setup.json").text());
console.log(JSON.stringify({state:d.state,verify:d.verify,notes:d.notes,instructions:d.instructions?.action},null,1));
for (const n of d.notices||[]) { console.log("NOTICE",n.code,n.kind); console.log(n.user_message); for (const x of n.decisions||[]) console.log(" -",x.id,"default=",JSON.stringify(x.default),"|",x.default_reason); }
'

export PATH="$HOME/.bun/bin:$PATH"; mkdir -p /harness-state/tmp/gbrain-verify; cd /harness-state/tmp/gbrain-verify
gbrain put test/gbrain-install-check --content-origin inferred --content $'---\ntitle: GBrain install check\n---\n# GBrain install check\n\nGeneric install test note. Keyword marker: osprey-4482.\n' 2>&1 | tail -3; echo "put exit=$?"
cat > mcp-check.ts <<'EOF'
const p = Bun.spawn(["/harness-state/.gbrain/hook-launcher/gbrain-hook","/harness-state/.bun/bin/gbrain","serve","--surface","starter","--advertise","verbs"],{stdin:"pipe",stdout:"pipe",stderr:"ignore"});
const send=(o:any)=>{p.stdin.write(JSON.stringify(o)+"\n");p.stdin.flush();};
const reader=p.stdout.getReader(); let buf=""; const dec=new TextDecoder();
async function read(id:number){for(;;){const i=buf.indexOf("\n");if(i>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);try{const m=JSON.parse(l);if(m.id===id)return m;}catch{}continue;}const {value,done}=await reader.read();if(done)throw new Error("eof");buf+=dec.decode(value);}}
send({jsonrpc:"2.0",id:1,method:"initialize",params:{protocolVersion:"2025-06-18",capabilities:{},clientInfo:{name:"install-check",version:"1"}}}); await read(1);
send({jsonrpc:"2.0",method:"notifications/initialized"});
send({jsonrpc:"2.0",id:2,method:"tools/list"}); console.log("tools:", (await read(2)).result.tools.map((t:any)=>t.name).join(", "));
send({jsonrpc:"2.0",id:3,method:"tools/call",params:{name:"recall",arguments:{entity:"gbrain-install-check"}}}); console.log("MCP recall:", JSON.stringify((await read(3)).result).slice(0,400));
send({jsonrpc:"2.0",id:4,method:"tools/call",params:{name:"request_tools",arguments:{}}}); await read(4);
send({jsonrpc:"2.0",id:5,method:"tools/call",params:{name:"search",arguments:{query:"osprey-4482"}}}); console.log("MCP search:", JSON.stringify((await read(5)).result).slice(0,400));
p.kill(); process.exit(0);
EOF
timeout 120 bun run mcp-check.ts

